fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        // If length is 0 or 1, return (a, empty)
        // This satisfies:
        // - concatenation = original
        // - sum of lengths = original length
        // - if length <= 1, no requirement on strict shorter
        (a, Vec::new())
    } else {
        // length > 1
        // split roughly in half to ensure each is strictly shorter
        let mid = n / 2;
        // mid is at least 1 and less than n
        // so both parts are shorter than original
        let left = a[..mid].to_vec();
        let right = a[mid..].to_vec();
        (left, right)
    }
}